/// <summary>
/// NDX_MultipleS_Chain_Item
/// </summary>
class NDX_MultipleS_Chain_Item extends NDX_MultipleSelect_Chain
{
    InventTable          inventTable;

}

Method.Source:
protected void new(InventTable _inventTable, smmBusRelChainGroup _smmBusRelChainGroup = null)
{
    NDXMultipleS_smmBusrelChainGroup nDX_MultipleS_Chain;

    super();

    inventTable          = _inventTable;

    if(_smmBusRelChainGroup)
    {
        smmBusRelChainGroup = _smmBusRelChainGroup;
        companyChainId  = smmBusRelChainGroup.ChainId;
    }

    itemValidityErrors.ValidityCheckType = NDXValidityCheckType::Chain;
    itemValidityErrors.checkMessage      = strfmt("@NDX:NDXItemValidityChainTest", companyChainId);

    while select  nDX_MultipleS_Chain
        where nDX_MultipleS_Chain.RefRecId_InventTable == inventTable.RecId
    {
        nDX_SelectionTmp.RefRecId_smmBusRelChainGroup = nDX_MultipleS_Chain.RefRecId_smmBusRelChainGroup;
        nDX_SelectionTmp.doInsert();
    }

}

static public NDX_MultipleS_Chain_Item construct(InventTable _inventTable, smmBusRelChainGroup _smmBusRelChainGroup = null)
{
    return new NDX_MultipleS_Chain_Item(_inventTable, _smmBusRelChainGroup);
}

/// <summary>
/// Constructor
/// </summary>
/// <param name = "_obj">NDX_ItemValidity</param>
/// <param name = "_smmBusRelChainGroup">smmBusRelChainGroup</param>
/// <returns>NDX_MultipleS_Chain_Item object</returns>
static NDX_MultipleS_Chain_Item new_FromNDX_ItemValidity(NDX_ItemValidity _obj, smmBusRelChainGroup _smmBusRelChainGroup)
{
    NDX_MultipleS_Chain_Item      nDX_MultipleS_Chain_Item;
    ;
    nDX_MultipleS_Chain_Item = new NDX_MultipleS_Chain_Item(_obj.parmInventTable(), _smmBusRelChainGroup);
    nDX_MultipleS_Chain_Item.parmOItemValidity(_obj);
    return nDX_MultipleS_Chain_Item;

}

/// <summary>
/// Checks if item is valid for chain group
/// </summary>
/// <returns>container</returns>
public container isValid()
{
    NDXValidityMessage validityMessage = '';
    boolean     lIsValid = true;
    ;

    oItemValidity.parmChecked_Chain(companyChainId);

    // keine Gültigkeitsprüfung hinterlegt
    if (nDX_SelectionTmp.RecId == 0)
    {
        return [lIsValid, validityMessage];
    }

    select firstonly nDX_SelectionTmp where nDX_SelectionTmp.RefRecId_smmBusRelChainGroup == smmBusRelChainGroup.RecId;

    if (nDX_SelectionTmp)
    {
        return [lIsValid, validityMessage];
    }

    lIsValid        = false;

    // Der Artikel darf nur an Debitoren der Ketten [%1] %2 werden!
    validityMessage = strFmtLB(strfmt("@NDX:NDXItemValidityChainMassage", NDXMultipleS_smmBusRelChainGroup::range2String(inventTable.RecId), oItemValidity.parmCheckType() == NDXValidityCheckType::SalesNumber ? "@NDX:NDXItemValidityToSold" : "@NDX:NDXItemValidityToOffered"));

    itemValidityErrors.ErrorMessage = validityMessage;
    oItemValidity.addErrorMessage(itemValidityErrors);

    return [lIsValid, validityMessage];
}

static void main(Args args = new Args())
{
    InventTable                     inventTable;
    NDX_MultipleS_Chain_Item        multipleSelectClass;
    ;
    if (args.dataset() == tablenum(InventTable))
    {
        inventTable = args.record();
        multipleSelectClass = new NDX_MultipleS_Chain_Item(inventTable);
        multipleSelectClass.openSelectForm();
    }
}
